#!/usr/bin/env node
// Writes requests.csv from the change requests people raise on GitHub.
// One row per request. Regenerated by .github/workflows/requests.yml whenever an
// issue is opened, edited, closed or reopened, so it stays current on its own.
import { execSync } from "node:child_process";
import { writeFileSync, readFileSync, existsSync } from "node:fs";

const REPO = "palsampurna16-prog/cdlc-workflow-record";

function token() {
  if (process.env.GITHUB_TOKEN) return process.env.GITHUB_TOKEN;
  try { return execSync("gh auth token", { encoding: "utf8" }).trim(); }
  catch { return null; }
}

const t = token();
if (!t) {
  console.error("No GitHub token. Set GITHUB_TOKEN, or sign in with: gh auth login");
  process.exit(1);
}

const issues = [];
for (let page = 1; page <= 10; page++) {
  const res = await fetch(
    `https://api.github.com/repos/${REPO}/issues?state=all&per_page=100&page=${page}`,
    { headers: { Authorization: `Bearer ${t}`, Accept: "application/vnd.github+json" } });
  if (!res.ok) { console.error(`GitHub said ${res.status}: ${await res.text()}`); process.exit(1); }
  const batch = await res.json();
  if (!batch.length) break;
  issues.push(...batch.filter(i => !i.pull_request));   // pull requests are not requests
}

/* the button writes the page under a "Which page" heading, so pull it back out */
const pageOf = body => {
  const m = /\*\*Which page\*\*\s*\n([^\n]*)/.exec(body || "");
  return m ? m[1].trim() : "";
};
const section = (body, name) => {
  const re = new RegExp(`\\*\\*${name}\\*\\*\\s*\\n([\\s\\S]*?)(?=\\n\\*\\*|$)`);
  const m = re.exec(body || "");
  return m ? m[1].trim().replace(/\s*\n\s*/g, " ") : "";
};

/* GitHub's list endpoint lags a few seconds behind a new issue. A run triggered by
   that very issue can therefore see nothing. Refuse to replace a sheet that has rows
   with one that has none, so a slow read cannot erase real requests. */
const out = new URL("../requests.csv", import.meta.url);
if (!issues.length && existsSync(out)) {
  const existing = readFileSync(out, "utf8").trim().split("\n").length - 1;
  if (existing > 0) {
    console.log(`GitHub returned no requests but the sheet holds ${existing}. Leaving it alone.`);
    process.exit(0);
  }
}

const q = v => '"' + String(v ?? "").replace(/"/g, '""') + '"';
const rows = issues.map(i => [
  (i.created_at || "").slice(0, 10),
  (i.created_at || "").slice(11, 16),
  i.user?.login || "",
  i.title.replace(/^Change request:\s*/, ""),
  pageOf(i.body),
  section(i.body, "What should change"),
  section(i.body, "Why / what is wrong today"),
  i.state === "closed" ? "Done" : "Open",
  (i.closed_at || "").slice(0, 10),
  i.number,
  i.html_url,
]);

const csv = [
  ["Date", "Time", "Raised by", "Request", "Page", "What should change",
   "Why", "Status", "Closed on", "Number", "Link"].map(q).join(","),
  ...rows.map(r => r.map(q).join(",")),
].join("\n");

writeFileSync(out, "﻿" + csv + "\n");
console.log(`requests.csv written, ${rows.length} request${rows.length === 1 ? "" : "s"}`);
